data.query:
query Inventory($whereSource: InventoryWhereInput, $whereDestination: InventoryWhereInput) {
  sourceInventory: inventory(where: $whereSource) {
    edges {
      node {
        id
        active
        inventoryStatusId
        serialNumber
        quantity {
          value
          unitId
          unit {
            name
            unitTypeId
          }
        }
        shippable
        barcode
        trackingNumber
        note
        grossWeight {
          value
          unitId
          unit {
            name
            unitTypeId
          }
        }
        netWeight {
          value
          unitId
          unit {
            name
            unitTypeId
          }
        }
        expiresAt
        lastCountAt
        manufacturedAt
        workOrderId
        externalId
        extProductId
        extProcessId
        customData
        integrationData
        handlingUnitId
        inventoryStatusId
        inventoryStatus { code }
        storageUnitId
        lotId
        processId
        productId
        product { id number revision gtin sku upc weight{value unitId} }
        receiptLineId
      }
    }
  }

  destinationInventory: inventory(where: $whereDestination) {
    edges {
      node {
        id
        active
        inventoryStatusId
        serialNumber
        quantity {
          value
          unitId
          unit {
            name
            unitTypeId
          }
        }
        shippable
        barcode
        trackingNumber
        note
        grossWeight {
          value
          unitId
          unit {
            name
            unitTypeId
          }
        }
        netWeight {
          value
          unitId
          unit {
            name
            unitTypeId
          }
        }
        expiresAt
        lastCountAt
        manufacturedAt
        workOrderId
        externalId
        extProductId
        extProcessId
        customData
        integrationData
        handlingUnitId
        inventoryStatusId
        storageUnitId
        lotId
        processId
        productId
        product { id number revision gtin sku upc weight{value unitId}}
        receiptLineId
      }
    }
  }
}

