data.transform:
(
  /* Flatten results from units query */
  $units := unit.edges.node ~> | $ | {
    "conversions": $coalesce([conversions.edges.node, []])
  } |;

  /* Add context to quantities */
  $addUnitInfo := function($quantity) {(
    $unitId := $quantity.unitId;
    $quantity ~> | $ | {
      "unit": $units[id = $unitId]
    } |;
  )};
  
  $state.context.({
    "units": $units,
    "mergeQty": $addUnitInfo(mergeQty),
    "sourceInventory": sourceInventory.({
      "quantity": $addUnitInfo(quantity),
      "grossWeight": grossWeight ? $addUnitInfo(grossWeight),
      "netWeight": netWeight ? $addUnitInfo(netWeight)
    }),
    "destinationInventory": destinationInventory.({
      "quantity": $addUnitInfo(quantity),
      "grossWeight": grossWeight ? $addUnitInfo(grossWeight),
      "netWeight": netWeight ? $addUnitInfo(netWeight)
    })
  });
)

