data.query:
query Unit($where: UnitWhereInput, $orderBy: [UnitOrderByInput!], $first: Int, $after: String) {
  unit(where: $where, orderBy: $orderBy, first: $first, after: $after) {
    edges {
      node {
        id
        unitTypeId
        unitType {
          id
          label
          description
        }
        name
        code
      }
    }
  }
}

