data.variablesTransform:
$state.context.({
  "sourcePayload": sourceInventory.({
    "update": {
      "handlingUnitId": null,
      "active": false,
      "quantity": { "value": 0 },
      "inventoryStatusId": "retired",
      "netWeight": $exists(netWeight.value) ? {
        "value": 0
      },
      "grossWeight": $exists(grossWeight.value) and $exists(netWeight.value) ? {
        "value": grossWeight.value - netWeight.value
      },
      "lastTransactionTypeId": "inventoryMerge"
    },
    "where": {
      "id": id
    }
  }),

  "destinationPayload": {
    "update": {
      "quantity": {
        "value": sourceInventory.quantity.value + destinationInventory.quantity.value
      },
      "grossWeight": $exists(destinationInventory.grossWeight.value) and $exists(sourceInventory.netWeight.value) ? {
        "value": destinationInventory.grossWeight.value + sourceInventory.netWeight.value
      },
      "netWeight": $exists(destinationInventory.netWeight.value) and $exists(sourceInventory.netWeight.value) ? {
        "value": destinationInventory.netWeight.value + sourceInventory.netWeight.value
      },
      "lastTransactionTypeId": "inventoryMerge"
    },
    "where": {
      "id": destinationInventory.id
    }
  }
})

