}

data.responseTransform:
$state.context.(
  
  $symmetricDifference := function($a, $b) {
    $abs(2 * ($a - $b) / ($a + $b))
  };

  /* It's technically only density if the quantity unit is volumetric, but it helps to visualize what we're doing here */
  $sourceDensity := sourceInventory.netWeight.value / sourceInventory.quantity.value;
  $destinationDensity := destinationInventory.netWeight.value / destinationInventory.quantity.value;

  {
    "success": false,
    "severity": "error",
    "title": "Inventory Weight Ratio Difference",
    "message": "The quantity-to-weight ratios of the source inventory are more than 2% different from one another, which may be a sign of invalid weight or quantity values. Because the merge operation automatically adds weight to the destination inventory based on the merge quantity, a merge cannot be performed on the selected source and destination inventory.",
    "data": {
      "Source Inventory Quantity": sourceInventory.($string(quantity.value) & " " & quantity.unit.code),
      "Source Inventory Net Weight": sourceInventory.($string(netWeight.value) & " " & netWeight.unit.code),
      "Source Inventory Weight Ratio": sourceInventory.($string($sourceDensity) & " " & netWeight.unit.code & "/" & quantity.unit.code),
      "Destination Inventory Quantity": destinationInventory.($string(quantity.value) & " " & quantity.unit.code),
      "Destination Inventory Net Weight": destinationInventory.($string(netWeight.value) & " " & netWeight.unit.code),
      "Destination Inventory Weight Ratio": destinationInventory.($string($sourceDensity) & " " & netWeight.unit.code & "/" & quantity.unit.code),
      "Weight Ratio Error": $formatNumber($symmetricDifference($sourceDensity, $destinationDensity), "0.00%"),
      "context": input.debugMode ? $state.context,
      "payload": input.debugMode ? $$
    }
  };
)

$state.context.(

  $isZero := function($n) {
    $round($abs($n), 15) = 0
  };

  {
    "success": false,
    "severity": "error",
    "title": "Inventory Weight Missing",
    "message": "If either the source inventory or the destination inventory have a non-zero weight value, then both must have a non-zero weight value. If not, this could be a sign of missing weight information. Because the merge operation automatically adds weight to the destination inventory based on the merge quantity, a merge cannot be performed on the selected source and destination inventory.",
    "data": {
        "Source Inventory": sourceInventory.({
          "Gross Weight": $string(grossWeight.value) & " " & grossWeight.unit.code,
          "Net Weight": $string(netWeight.value) & " " & netWeight.unit.code
        }),
        "Destination Inventory": destinationInventory.({
          "Gross Weight": $string(grossWeight.value) & " " & grossWeight.unit.code,
          "Net Weight": $string(netWeight.value) & " " & netWeight.unit.code
        }),
        "context": input.debugMode ? $state.context,
        "payload": input.debugMode ? $$
      }
  };
)

