        "quantity": { "value": $sourceNewQuantity },
        "netWeight": { "value": $sourceNewWeightValue },
        "grossWeight": { "value": $sourceNewWeightValue },
        "lastTransactionTypeId": "inventoryMerge",
        "inventoryStatusId": $retireContainer ? "retired" : retireContainer
      },
      "where": {
        "id": sourceInventory.id
      }
    },

    "destinationPayload": {
      "update": {
        "quantity": { "value": $destinationNewQuantity },
        "netWeight": { "value": $destinationNewWeightValue },
        "grossWeight": { "value": $destinationNewWeightValue },
        "lastTransactionTypeId": "inventoryMerge"
      },
