    $join([$lines, $everythingElse], "\n");

  )};

  $metadata.urlParameters.businessPartnerId?(
    $data :=data~>| $ | { 
      "businessPartnerId": $metadata.urlParameters.businessPartnerId,
      "textAddress": textAddress? textAddress : $addressToString(address) 
      }, 
      ["total", "edges", "id"] |;
    
    {
      "payload":{
        "create": $data    
      }
    }
  )
  :
  $throw("No Business Partner Id Provided.")
)

