query (
  $countId: String!,
  $storageUnitCode: String
  $first: Int
){
  countLine(
    first: $first
    where:{
      countId: {
        _eq: $countId 
      }
      expectedStorageUnit:  {
         code:  {
            _contains: $storageUnitCode
         }
      }
    }
  ){
    total
    edges{
      node{
        id
        expectedStorageUnit{
          id
          code
        }
        _aggregate{
          expectedStorageUnitId{
            uniqueValues
          }
        }
      }
    }
  }

  countLineInventory(
    first: $first
    where:{
      countLine:  {
        countId: {
          _eq: $countId 
        }
        expectedStorageUnit:  {
         code:  {
            _contains: $storageUnitCode
         }
        }   
      }

    }
  ){
    total
    edges{
      node{
        id
        countLine{
          expectedStorageUnitId
        }
        quantity{
          _aggregate{
            value{
              sum
            }
          }
        }

      }
    }
  }

  counted: countLineInventory(
    first: $first
    where:{
      counterUserId:  {
         _isNull: false
      }
      countLine:  {
        countId: {
          _eq: $countId 
        }
        expectedStorageUnit:  {
          code:  {
              _contains: $storageUnitCode
          }
        }   
      }

    }
  ){
    total
    edges{
      node{
        id
        countLine{
          expectedStorageUnitId
        }
        quantity{
          _aggregate{
            value{
              sum
            }
          }
        }

      }
    }
  }

  storageUnit(
    first: $first
    where:  {
       code:  {
          _contains: $storageUnitCode
       }
    }
  ){
    edges{
      node{
        code id
      }
    }
  }
}

